__NUXT_JSONP__("/jp/material/thanks", (function(a){return {data:[{details:{slug:"jp",pageTitle:"資料のダウンロードありがとうございます | Mentor Language Institute",pageDescription:"この度は資料請求、誠にありがとうございます。  ※同様の内容をメールでもお送りさせて頂いております。",title:"資料のダウンロードありがとうございます",subtitle:["この度は資料請求、誠にありがとうございます。 \u003Cbr \u002F\u003E ※同様の内容をメールでもお送りさせて頂いております。","資料はこちらよりダウンロード下さい。"],brochures:[{title:"学校概要パンフレット（日本語）",image:"\u002Fimages\u002Fmaterial\u002Fmli-brochure-program-schedule-en.png",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F[Japanese]MLI School Brochure.pdf"},{title:"寮・ホームステイについての資料（英語）",image:"\u002Fimages\u002Fmaterial\u002F2022-housing-brochure.png",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002FUSSS Student Housing Brochure(updated 10.16.2024).pdf"},{title:"2026 Price & Enrollment Package (英語)",image:"\u002Fimages\u002Fmaterial\u002F2026-price-package.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2026 MLI Info Pack updated_9.17.25.pdf"},{title:"2026 MLI アクティビティ・パンフレット",image:"\u002Fimages\u002Fmaterial\u002F2026 MLI Activity.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2026 MLI Activity Calendar Brochure.pdf"},{title:"2027 MLI アクティビティ・パンフレット",image:"\u002Fimages\u002Fmaterial\u002F2027 MLI Activity.PNG",link_text:a,link:"\u002Fdocuments\u002Fbrochure\u002F2027 MLI Activity Calendar Brochure 10.1.26.pdf"}],other_info:["\u003Cspan class='hutoaka'\u003Eお問合せはアドミッションスタッフが対応致します。\u003C\u002Fspan\u003E\u003Cbr \u002F\u003E学生ビザ、滞在先の空き状況、その他ご質問ございましたら、お気軽にお問合せ下さい！","複雑な留学手続きについて電話でご案内させて頂くことも可能です。","「電話による説明を希望しない」にチェックを入れなかった場合は、1~2日以内に電話でご連絡させて頂きます。","\u003Cb\u003E【ウエストウッドキャンパス】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E10880 Wilshire Blvd., Suite 122\u003Cbr \u002F\u003ELos Angeles, CA 90024\u003Cbr \u002F\u003E電話番号: ＋1（310）887-0777\u003Cbr \u002F\u003Eメールアドレス: info@mliesl.edu\u003Cbr \u002F\u003E営業時間: 月曜日~木曜日 8:30 - 20:30, 金曜日 8:30 - 18:00","\u003Cb\u003E【ハリウッドキャンパス】\u003C\u002Fb\u003E\u003Cbr \u002F\u003E7080 Hollywood Blvd., Suite 314\u003Cbr \u002F\u003ELos Angeles, CA 90028\u003Cbr \u002F\u003E電話番号: ＋1（323）870-7102\u003Cbr \u002F\u003Eメールアドレス: hollywood@mliesl.edu\u003Cbr \u002F\u003E営業時間: 月曜日~金曜日 8:30 - 17:00"],dir:"\u002Fmaterial-thanks",path:"\u002Fmaterial-thanks\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:29.893Z",updatedAt:"2026-11-24T13:32:55.925Z"}}],fetch:{},mutations:void 0}}("\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E Download")));